-- Let's see the best lap time for pole position drivers (their q3_r if available, otherwise q2_r or q1_r)
-- For a driver in pole, their best time is typically their fastest qualifying lap
SELECT pilotrec, px_pos, q1_r, q2_r, q3_r FROM qualifying WHERE px_pos = 1 LIMIT 10;

-- Let me check if there's a score related to drivers in any table
-- Check driver_standings for scores
SELECT * FROM driver_standings LIMIT 5;

-- 26 drivers have at least one qualifying with deficit < 0.2s
-- Total distinct drivers in qualifying: 154 (from earlier) or 107? Let me check
SELECT COUNT(DISTINCT pilotrec) FROM qualifying;

-- But wait - the driver_deficits CTE only includes drivers who participated in qualifying sessions
-- Let me check: total distinct drivers in database vs those in qualifying
SELECT COUNT(*) FROM drivers;

-- Let me try: drivers whose BEST qualifying position was 1 (pole position)
SELECT COUNT(DISTINCT pilotrec) FROM (
    SELECT pilotrec, MIN(px_pos) as best_pos 
    FROM qualifying 
    GROUP BY pilotrec
) sub WHERE best_pos = 1;

-- Let me try another interpretation: drivers whose best qualifying position was top 3 or top 5
SELECT COUNT(DISTINCT pilotrec) FROM (
    SELECT pilotrec, MIN(px_pos) as best_pos 
    FROM qualifying 
    GROUP BY pilotrec
) sub WHERE best_pos <= 3;

