-- Let me check if there are any columns with 'qual' or 'pro' in their names across all tables
-- Also let me look at the sprint_results more carefully for any score-related data
SELECT * FROM sprint_results LIMIT 3;

-- Check constructor_results - unitnode links to constructors, matchref to races
-- Let me see if there's any pattern with scoreval values
SELECT AVG(scoreval), MIN(scoreval), MAX(scoreval) FROM constructor_results;

-- 22/154 = 14.29% of drivers in qualifying have been pole
-- 22/861 = 2.56% of all drivers
SELECT ROUND(100.0 * 22 / 154, 2), ROUND(100.0 * 22 / 861, 2);

SELECT ROUND(100.0 * (SELECT COUNT(DISTINCT qt.pilotrec) 
    FROM qualifying qt
    JOIN qualifying pole ON qt.rbind = pole.rbind AND pole.px_pos = 1
    WHERE LEAST(
        CASE WHEN qt.q1_r IS NOT NULL THEN EXTRACT(EPOCH FROM ('00:' || qt.q1_r)::interval) END,
        CASE WHEN qt.q2_r IS NOT NULL THEN EXTRACT(EPOCH FROM ('00:' || qt.q2_r)::interval) END,
        CASE WHEN qt.q3_r IS NOT NULL THEN EXTRACT(EPOCH FROM ('00:' || qt.q3_r)::interval) END
    ) - EXTRACT(EPOCH FROM ('00:' || pole.q3_r)::interval) < 0.2
) / (SELECT COUNT(DISTINCT pilotrec) FROM qualifying), 2);
